<script setup>
import {computed} from 'vue'
const props=defineProps({problem:{type:Object,required:true},state:{type:Object,required:true}})
const positions=computed(()=>{
 const names=props.problem.variables
 if(names.includes('WA'))return {WA:[55,130],NT:[165,55],SA:[170,190],Q:[280,85],NSW:[300,190],V:[250,275],T:[100,300]}
 if(names.length<=6)return Object.fromEntries(names.map((v,i)=>[v,[65+(i%3)*120,70+Math.floor(i/3)*170]]))
 return Object.fromEntries(names.map((v,i)=>[v,[45+(i%5)*70,50+Math.floor(i/5)*65]]))
})
const edges=computed(()=>props.problem.constraints.filter((c,i,all)=>all.findIndex(x=>[x.a,x.b].sort().join('|')===[c.a,c.b].sort().join('|'))===i))
const active=computed(()=>props.state.propagation?.arc||props.state.arc||[])
const domains=computed(()=>props.state.propagation?.domains||props.state.domains)
const color=value=>value==='Đỏ'?'red':value==='Lá'?'green':value==='Lam'?'blue':''
</script>
<template><div class="csp-state"><svg v-if="problem.variables.length<=10" viewBox="0 0 370 335" role="img" aria-label="Đồ thị ràng buộc, nút là biến và cạnh là quan hệ"><line v-for="(c,i) in edges" :key="i" :x1="positions[c.a][0]" :y1="positions[c.a][1]" :x2="positions[c.b][0]" :y2="positions[c.b][1]" :class="{active:active.includes(c.a)&&active.includes(c.b)}"/><g v-for="v in problem.variables" :key="v"><circle :cx="positions[v][0]" :cy="positions[v][1]" r="24" :class="[{assigned:Object.hasOwn(state.assignment||{},v),empty:!domains[v].length},color(state.assignment?.[v])]"/><text :x="positions[v][0]" :y="positions[v][1]+6" text-anchor="middle">{{ v }}</text></g></svg><div class="csp-domains"><article v-for="v in problem.variables" :key="v" :class="{empty:!domains[v].length,chosen:state.variable===v||active[0]===v}"><strong>{{ v }}</strong><span v-if="Object.hasOwn(state.assignment||{},v)" class="assigned-value">= {{ state.assignment[v] }}</span><div class="domain-values"><span v-for="value in problem.domains[v]" :key="value" :class="[color(value),{deleted:!domains[v].includes(value)}]">{{ value }}</span><span v-if="!domains[v].length">Miền rỗng</span></div></article></div></div></template>
<style scoped>
.csp-state{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;align-items:start;min-width:0}.csp-state svg{width:100%;height:auto;background:var(--paper)}svg line{stroke:var(--ink-2);stroke-width:1.2;vector-effect:non-scaling-stroke}svg line.active{stroke:var(--tim);stroke-width:2.5}svg circle{fill:var(--paper);stroke:var(--ink-2);stroke-width:1.5}svg circle.assigned{stroke:var(--tim);stroke-width:3}svg circle.red{fill:var(--do-soft)}svg circle.green{fill:var(--xanh-soft)}svg circle.blue{fill:var(--tim-soft)}svg circle.empty{stroke:var(--do);stroke-dasharray:4 3}svg text{font:16px var(--font-ui);fill:var(--ink)}.csp-domains{display:grid;gap:8px}.csp-domains article{border:1px solid var(--rule);border-radius:var(--radius);background:var(--paper);padding:8px;font:var(--fs-small)/1.6 var(--font-ui)}.csp-domains article.chosen{border-left:3px solid var(--tim)}.csp-domains article.empty{border-color:var(--do)}.assigned-value{margin-left:6px}.domain-values{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}.domain-values span{border:1px solid var(--control);border-radius:var(--radius);padding:2px 5px}.domain-values span.red{border-color:var(--do)}.domain-values span.green{border-color:var(--xanh)}.domain-values span.blue{border-color:var(--tim)}.domain-values span.deleted{text-decoration:line-through;opacity:.45}@media(max-width:600px){.csp-state{grid-template-columns:1fr}.csp-state svg{max-width:340px;margin:auto}.csp-domains{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(prefers-reduced-motion:no-preference){.csp-domains article{transition:border-color .15s}}
</style>
